package com.noven.ncrawler.ui.components

import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp

// The animated settings icon (settingsV2.json, Feather "sliders": the three knobs
// slide), played natively by LottieLite — no lottie dependency, same approach as
// AnimatedRefreshIcon.
//
// It is state-driven, not a looping decoration: [active] = true plays the file
// forward (the knobs slide, 10 frames = ~330ms) and HOLDS the last pose while
// whatever it opens is on screen; [active] = false slides them back (a touch
// quicker — closing is the less important half). Frame 0 is the resting icon.
// System "Remove animations" -> a still icon.

private val SLIDERS_ICON by lazy { LottieIcon(SLIDERS_JSON) }

@Composable
fun AnimatedSlidersIcon(
    active: Boolean,
    ink: Color,
    modifier: Modifier = Modifier,
    // The file's canvas is 32 with the 24-unit glyph centred in it, so 32.dp
    // draws the glyph at 24.dp — the size of every other icon button.
    size: Dp = 32.dp
) {
    val icon = SLIDERS_ICON
    val reduced = rememberReducedMotion()
    val phase = remember { Animatable(0f) }

    LaunchedEffect(active, reduced) {
        if (reduced) {
            phase.snapTo(0f)
        } else {
            val ms = if (active) icon.durationMs else (icon.durationMs * 0.8f).toInt()
            phase.animateTo(if (active) 1f else 0f, tween(ms.coerceAtLeast(1), easing = LinearEasing))
        }
    }

    Canvas(modifier.size(size)) {
        // phase is read here, in the draw phase — no recomposition per frame.
        icon.draw(this, icon.frameAt(phase.value), ink, ink)
    }
}

